import {createGame,start,swap,play,pickup,zone,legal,rankName,chooseMove,topRank,assertGame} from './engine.js';
const $=id=>document.getElementById(id),KEY='shithead-table-v2';let game,selected=[],swapHand=null,timer=null,sound=false,audio,stats={you:0,fox:0},notice='';
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.game){assertGame(saved.game);game=saved.game;stats=saved.stats||stats;}}catch{}game||=createGame();
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify({game,stats}));}catch{}};
const names={'♠':'spade','♥':'heart','♣':'club','♦':'diamond'};
function svgCard(c,back=false){const id=back?'alternate-back':c.rank===15?(c.id.includes('red')?'joker_red':'joker_black'):`${names[c.suit]}_${({11:'jack',12:'queen',13:'king',14:'1'})[c.rank]||c.rank}`;return `<svg viewBox="0 0 169.075 244.64" aria-hidden="true"><use href="assets/cards.svg#${id}" fill="#2b5959"/></svg>`;}
function card(c,{back=false,action=null,active=false,chosen=false,style='',disabled=false}={}){const b=document.createElement(action?'button':'div');b.className=`card${back?' back':''}${active?' playable':''}${chosen?' selected':''}`;b.innerHTML=svgCard(c,back);b.style.cssText=style;if(action){b.type='button';b.dataset.cardId=c.id;b.setAttribute('aria-label',back?'Play face-down card':`${rankName(c.rank)}${c.rank===15?'':' of '+names[c.suit]+'s'}`);b.setAttribute('aria-pressed',String(chosen));b.disabled=disabled;b.onclick=action;}return b;}
function blip(burn=false){if(!sound)return;try{audio||=new AudioContext();audio.resume();const o=audio.createOscillator(),a=audio.createGain();o.type='sine';o.frequency.setValueAtTime(burn?660:340,audio.currentTime);o.frequency.exponentialRampToValueAtTime(burn?980:190,audio.currentTime+.12);a.gain.setValueAtTime(.045,audio.currentTime);a.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.17);o.connect(a);a.connect(audio.destination);o.start();o.stop(audio.currentTime+.18);}catch{}}
function reserve(who){const p=game.players[who],container=who?$('opponent-cards'):$('player-table');container.replaceChildren();const group=document.createElement('div');group.className='opponent-reserve';if(!who){group.style.display='contents';}const count=Math.max(p.down.length,p.up.length);for(let i=0;i<count;i++){const slot=document.createElement('div');slot.className='reserve-slot';if(p.down[i]){const down=p.down[i];slot.append(card(down,{back:true,action:!who&&game.phase==='playing'&&game.turn===0&&zone(p)==='down'?()=>move([down.id]):null,active:!who&&game.phase==='playing'&&game.turn===0&&zone(p)==='down'}));}if(p.up[i]){const up=p.up[i];const enabled=!who&&(game.phase==='setup'||game.phase==='playing'&&game.turn===0&&zone(p)==='up');slot.append(card(up,{action:enabled?()=>tableSelect(up):null,active:enabled&&game.phase==='playing'&&legal(up,game.pile,game.lowTurns),chosen:selected.includes(up.id)}));}group.append(slot);}container.append(group);if(who){const hand=document.createElement('div');hand.className='opponent-hand';for(let i=0;i<Math.min(5,p.hand.length);i++)hand.append(card(p.hand[i],{back:true}));const count=document.createElement('small');count.textContent=p.hand.length+' in hand';hand.append(count);container.append(hand);}}
function tableSelect(c){if(game.phase==='setup'){if(!swapHand){notice='Select a card in your hand first, then a face-up card.';render();return;}swap(game,swapHand,c.id);selected=[];swapHand=null;notice='Swapped. Save your strongest cards for the end.';render();save();}else select(c);}
function select(c){if(game.phase==='setup'){swapHand=swapHand===c.id?null:c.id;selected=swapHand?[swapHand]:[];notice=swapHand?'Now choose a face-up card to swap with.':'';}else{if(!legal(c,game.pile,game.lowTurns)){notice=game.lowTurns?`Play 7 or lower (${game.lowTurns} low ${game.lowTurns===1?'turn':'turns'} left), a 2, joker or 10.`:`Match or beat ${rankName(topRank(game.pile))}, or use a 2, joker or 10.`;render();return;}const old=game.players[0][zone(game.players[0])].find(c=>c.id===selected[0]);if(old&&old.rank!==c.rank)selected=[];selected=selected.includes(c.id)?selected.filter(id=>id!==c.id):[...selected,c.id];notice='';}render();}
function render(){const focus=document.activeElement?.dataset.cardId,p=game.players[0],op=game.players[1],z=zone(p),setup=game.phase==='setup',finished=game.phase==='finished',human=game.turn===0&&!finished&&!setup;reserve(0);reserve(1);$('human-score').textContent=stats.you;$('fox-score').textContent=stats.fox;$('fox-turn').hidden=setup||finished||human;$('fox-status').textContent=finished?(game.winner===1?'A sly win. Another round?':'Outfoxed. This time.'):game.turn===1&&!setup?'Weighing up the options…':`${op.hand.length+op.up.length+op.down.length} cards left. No tells.`;$('deck-count').textContent=game.deck.length?`${game.deck.length} in the deck`:'Deck is empty';$('stock').replaceChildren();if(game.deck.length)$('stock').append(card(game.deck[0],{back:true}));$('burn-count').textContent=game.burned.length;$('pile').replaceChildren();game.pile.slice(-3).forEach((c,i,a)=>$('pile').append(card(c,{style:`transform:rotate(${(i-a.length+1)*-7}deg)`})));$('table-stamp').hidden=game.pile.length>0;$('pile-caption').textContent=game.pile.length?`${game.pile.length} ${game.pile.length===1?'card':'cards'} in the pile`:'';$('direction').textContent=game.direction===1?'↻':'↺';$('direction').setAttribute('aria-label',game.direction===1?'Clockwise play':'Counterclockwise play');$('you-turn').textContent=setup?'SETTING UP':finished?(game.winner===0?'WINNER':'NEXT TIME'):human?'YOUR TURN':'WAITING';$('phase-label').textContent=setup?'Your last line of defense':p.hand.length?'Face-up cards · save these for later':p.up.length?'Your hand is empty. Play your face-up cards.':'The final stretch. Choose a face-down card.';$('hand-label').textContent=setup?'YOUR HAND':z==='hand'?`YOUR HAND · ${p.hand.length}`:z==='up'?'FACE-UP CARDS':'FACE-DOWN CARDS';$('hand-hint').textContent=setup?'Save your best cards for the end.':game.lowTurns?`${game.lowTurns} low ${game.lowTurns===1?'turn':'turns'} remaining`:'Matching ranks can be played together.';$('hand').replaceChildren();$('hand').classList.toggle('crowded',p.hand.length>6);const hand=[...p.hand].sort((a,b)=>a.rank-b.rank);hand.forEach((c,i)=>$('hand').append(card(c,{action:()=>select(c),disabled:!setup&&!human,active:human&&legal(c,game.pile,game.lowTurns),chosen:selected.includes(c.id),style:`--index:${i};--angle:${hand.length<=8?(i-(hand.length-1)/2)*3:0}deg`})));if(!hand.length){const empty=document.createElement('div');empty.className='hand-empty';empty.textContent=finished?(game.winner===0?'Beautifully played. You’re out.':'The Fox got out first.'):z==='up'?'Your face-up cards are in play. Select them on the table.':'No peeking. Pick a face-down card on the table.';$('hand').append(empty);}
$('play').disabled=!setup&&!finished&&(!human||!selected.length||z==='down');$('play').innerHTML=setup?`Let's play <span>→</span>`:finished?'Play again <span>→</span>':selected.length?`Play ${selected.length===1?'card':selected.length+' cards'} <span>→</span>`:'Select a card <span>→</span>';$('pickup').hidden=setup||finished||!human||!game.pile.length;$('hint').disabled=!human;$('announcement').textContent=notice||(!setup&&game.log[0])||'A good hand starts with a little scheming.';
let title,detail;if(setup){title=swapHand?'Choose a face-up card.':'Make yourself comfortable.';detail='Optional: select a hand card, then a face-up card to swap.';}else if(finished){title=game.winner===0?'You’re out. The Fox is the Shithead.':'Outfoxed. The next deal is yours.';detail='A fresh deck. A little revenge. Go again?';}else if(!human){title='The Fox is thinking.';detail='Your opponent is deciding what to leave you.';}else if(game.lowTurns){title=`Keep it low. ${game.lowTurns} low ${game.lowTurns===1?'turn':'turns'} left.`;detail='7 or lower · 2 always plays · joker passes through · 10 burns';}else if(z==='down'){title='Trust your luck.';detail='Choose a face-down card. A bad flip means picking up.';}else{const top=topRank(game.pile);title=top?`Your turn. Match or beat ${rankName(top)}.`:'An open table. Your move.';detail=game.pile.length?'Select matching cards, then play. Or pick up the pile.':'Play any card or matching set to open the pile.';}$('status-title').textContent=title;$('status-title').classList.toggle('win-title',finished);$('status-detail').textContent=detail;$('status-dot').style.background=finished?'#b78a36':human||setup?'#618151':'#b89c56';$('history-list').replaceChildren(...game.log.slice(0,60).map(msg=>{const li=document.createElement('li');li.textContent=msg;return li;}));if(focus)document.querySelector(`[data-card-id="${CSS.escape(focus)}"]`)?.focus({preventScroll:true});}
function after(result){if(!result.ok)return;selected=[];swapHand=null;notice='';blip(result.burn);if(result.blind)notice=`You flipped ${rankName(result.blind.rank)}. Too low — pick up the pile.`;if(game.phase==='finished'){if(game.winner===0)stats.you++;else stats.fox++;}game.log=game.log.slice(0,100);render();save();schedule();}
function move(ids){if(game.turn!==0||game.phase!=='playing')return;after(play(game,ids));}
function schedule(){clearTimeout(timer);if(game.phase==='playing'&&game.turn===1)timer=setTimeout(()=>{const ids=chooseMove(game);after(ids.length?play(game,ids):pickup(game));},1000);}
function newGame(){clearTimeout(timer);game=createGame();selected=[];swapHand=null;notice='';render();save();$('restart-dialog').close();}
$('play').onclick=()=>{if(game.phase==='setup'){selected=[];swapHand=null;notice='';start(game);render();save();}else if(game.phase==='finished')newGame();else move(selected);};$('pickup').onclick=()=>{if(game.turn===0)after(pickup(game));};
$('hint').onclick=()=>{if(game.turn!==0||game.phase!=='playing')return;const ids=chooseMove(game);if(zone(game.players[0])==='down'){notice='No way to know. Pick a face-down card and trust your luck.';}else if(ids.length){selected=ids;notice='Try this. Matching cards can go together.';}else notice='No legal cards this turn. Pick up the pile to keep going.';render();};
$('new-game').onclick=()=>game.phase==='setup'||game.phase==='finished'?newGame():$('restart-dialog').showModal();$('confirm-restart').onclick=newGame;$('cancel-restart').onclick=()=>$('restart-dialog').close();$('rules').onclick=()=>$('rules-dialog').showModal();$('credits').onclick=()=>$('credits-dialog').showModal();$('rules-credits').onclick=()=>{$('rules-dialog').close();$('credits-dialog').showModal();};document.querySelectorAll('.close-dialog,.close-rules').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));$('history-toggle').onclick=()=>{$('history').hidden=!$('history').hidden;$('history-toggle').textContent=$('history').hidden?'View table history ↗':'Hide table history ↙';};$('sound').onclick=()=>{sound=!sound;$('sound').textContent='Sound '+(sound?'on':'off');$('sound').setAttribute('aria-pressed',String(sound));blip();};document.addEventListener('keydown',e=>{if(e.key==='?'&&!document.querySelector('dialog[open]'))$('rules-dialog').showModal();if(e.key==='Enter'&&e.target===document.body&&!$('play').disabled)$('play').click();});render();schedule();
